fn loop_matches(info: &LoopInfo, backing: &std::fs::Metadata, readonly: bool) -> bool {
    info.device == backing.dev()
        && info.inode == backing.ino()
        && info.rdevice == backing.rdev()
        && info.offset == 0
        && info.sizelimit == 0
        && info.encrypt_type == 0
        && info.encrypt_key_size == 0
        && (info.flags & 1 != 0) == readonly
}


